import{_ as a,o as r,c as o,a3 as t}from"./chunks/framework.D5HvAqso.js";const g=JSON.parse('{"title":"What is DragDoll Solid?","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://niklasramo.github.io/dragdoll/solid/"}],["meta",{"property":"og:url","content":"https://niklasramo.github.io/dragdoll/solid/"}]]},"headers":[],"relativePath":"solid/index.md","filePath":"solid/index.md","lastUpdated":1778006798000}'),l={name:"solid/index.md"};function i(s,e,n,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="what-is-dragdoll-solid" tabindex="-1">What is DragDoll Solid? <a class="header-anchor" href="#what-is-dragdoll-solid" aria-label="Permalink to &quot;What is DragDoll Solid?&quot;">​</a></h1><p>DragDoll Solid is a thin and performant SolidJS wrapper for the <a href="/dragdoll/">DragDoll</a> drag-and-drop system. It provides hook-style helpers that give you access to the full DragDoll API while leveraging Solid&#39;s fine-grained reactivity for excellent performance.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>🎯   <strong>Thin Wrapper</strong>: Minimal overhead, direct access to vanilla DragDoll API.</p><p>🚀   <strong>High Performance</strong>: Leverages Solid&#39;s fine-grained reactivity with zero additional abstractions.</p><p>💪   <strong>Type Safe</strong>: Full TypeScript support with excellent type inference.</p><p>🍦   <strong>Vanilla Underneath</strong>: Full access to the underlying DragDoll API when you need it.</p><p>💝   <strong>Free &amp; Open Source</strong>: 100% MIT licensed.</p><h2 id="caveats" tabindex="-1">Caveats <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;Caveats&quot;">​</a></h2><p>Being a wrapper over a vanilla JS library often comes with a few caveats, and such is the case with this wrapper also. The <a href="/dragdoll/draggable#container"><code>container</code></a> option of the <a href="/dragdoll/draggable"><code>Draggable</code></a> class is only <em>partially</em> supported because it will make the core library move DOM nodes under a different node for the duration of the drag. Solid has its own API (<a href="https://docs.solidjs.com/concepts/control-flow/portal#portal" target="_blank" rel="noreferrer"><code>Portal</code></a>) for moving DOM nodes around, which is very tricky to support in a wrapper. Read more about this in the <a href="/dragdoll/solid/use-draggable#container"><code>useDraggable</code></a> docs.</p>',10)])])}const f=a(l,[["render",i]]);export{g as __pageData,f as default};
